method minSubArraySum(nums: array<int>) returns (result: int)
    requires nums.Length > 0 // Precondition: nums must not be empty
    ensures result == minSum // Postcondition: result is the minimum sum of any non-empty sub-array
    // where minSum is defined as the minimum sum of all possible non-empty sub-arrays of nums
{
    var minSum := nums[0]; // Initialize minSum with the first element
    var currentSum := 0; // Variable to hold the current sub-array sum

    // Iterate through the array to find the minimum sub-array sum
    for i := 0 to nums.Length - 1
        invariant 0 <= i <= nums.Length // Loop invariant: i is within bounds
        invariant currentSum + nums[i] <= minSum // Current sub-array sum is less than or equal to minSum
    {
        currentSum := min(0, currentSum + nums[i]); // Update currentSum
        minSum := min(minSum, currentSum); // Update minSum if currentSum is smaller
    }

    result := minSum; // Assign the result
}
